61	    @GetMapping("/comments")
62	    public ResponseEntity<List<Map<String, Object>>> getComments() {
63	        List<Comment> comments = commentRepository.findAllWithPostByOrderByCreatedAtDesc();
64	
65	        Set<Long> authorIds = comments.stream()
66	                .map(Comment::getAuthorId)
67	                .collect(Collectors.toSet());
68	
69	        Map<Long, UserInfoDTO> userMap;
70	        try {
71	            List<UserInfoDTO> users = userServiceClient.getUsersByIds(List.copyOf(authorIds));
72	            userMap = users.stream().collect(Collectors.toMap(UserInfoDTO::getId, u -> u));
73	        } catch (Exception e) {
74	            logger.warn("批量查询用户信息失败: {}", e.getMessage());
75	            userMap = Map.of();
76	        }
77	        final Map<Long, UserInfoDTO> finalUserMap = userMap;
78	
79	        List<Map<String, Object>> result = comments.stream().map(c -> {
80	            UserInfoDTO author = finalUserMap.get(c.getAuthorId());
81	            String postTitle = c.getPost() != null ? c.getPost().getTitle() : "未知帖子";
82	            return Map.<String, Object>of(
83	                    "id", c.getId(),
84	                    "postId", c.getPostId(),
85	                    "postTitle", postTitle,
86	                    "authorId", c.getAuthorId(),
87	                    "authorUsername", author != null ? author.getUsername() : "未知用户",
88	                    "content", c.getContent(),
89	                    "parentId", c.getParentId() != null ? c.getParentId() : 0L,
90	                    "status", c.getStatus(),
91	                    "createdAt", c.getCreatedAt().toString()
92	            );
93	        }).collect(Collectors.toList());
94	
95	        return ResponseEntity.ok(result);
96	    }
