10	
11	type TabType = 'posts' | 'comments' | 'reports';
12	
13	/**
14	 * 内容审核页面 - 帖子与评论审核
15	 */
16	export default function ContentModeration() {
17	  const queryClient = useQueryClient();
18	  const [activeTab, setActiveTab] = useState<TabType>('posts');
19	  const [filterStatus, setFilterStatus] = useState<string>('');
20	  const [error, setError] = useState('');
21	  const [success, setSuccess] = useState('');
22	
23	  // 帖子列表
24	  const { data: posts = [], isLoading: postsLoading } = useQuery({
25	    queryKey: queryKeys.admin.posts(filterStatus || undefined),
26	    queryFn: () => adminGetPosts(filterStatus || undefined),
27	    enabled: activeTab === 'posts',
28	  });
29	
30	  // 评论列表
31	  const { data: comments = [], isLoading: commentsLoading } = useQuery({
32	    queryKey: ['admin', 'comments'],
33	    queryFn: adminGetComments,
34	    enabled: activeTab === 'comments',
35	  });
36	
37	  // 举报列表
38	  const { data: reports = [], isLoading: reportsLoading } = useQuery({
39	    queryKey: ['admin', 'reports'],
40	    queryFn: adminGetReports,
41	    enabled: activeTab === 'reports',
42	  });
43	
44	  // 更新帖子状态
45	  const statusMutation = useMutation({
46	    mutationFn: ({ postId, status }: { postId: number; status: string }) =>
47	      adminUpdatePostStatus(postId, status),
48	    onSuccess: () => {
49	      queryClient.invalidateQueries({ queryKey: queryKeys.admin.posts() });
50	      setSuccess('状态更新成功');
51	    },
52	    onError: (err: any) => {
53	      setError(err.response?.data?.message || '更新失败');
54	    },
55	  });
56	
57	  // 删除帖子
58	  const deletePostMutation = useMutation({
59	    mutationFn: adminDeletePost,
60	    onSuccess: () => {
61	      queryClient.invalidateQueries({ queryKey: queryKeys.admin.posts() });
62	      setSuccess('帖子删除成功');
63	    },
64	    onError: (err: any) => {
65	      setError(err.response?.data?.message || '删除失败');
66	    },
67	  });
68	
69	  // 删除评论
70	  const deleteCommentMutation = useMutation({
71	    mutationFn: adminDeleteComment,
72	    onSuccess: () => {
73	      queryClient.invalidateQueries({ queryKey: ['admin', 'comments'] });
74	      setSuccess('评论删除成功');
75	    },
76	    onError: (err: any) => {
77	      setError(err.response?.data?.message || '删除失败');
78	    },
79	  });
80	
81	  // 处理举报
82	  const handleReportMutation = useMutation({
83	    mutationFn: ({ id, status }: { id: number; status: 'RESOLVED' | 'DISMISSED' }) =>
84	      adminHandleReport(id, status),
85	    onSuccess: () => {
86	      queryClient.invalidateQueries({ queryKey: ['admin', 'reports'] });
87	      setSuccess('举报处理成功');
88	    },
89	    onError: (err: any) => {
90	      setError(err.response?.data?.message || '处理失败');
91	    },
92	  });
93	
94	  const handleResolveReport = async (report: any) => {
95	    if (!confirm(`确定要处理此举报并删除该内容吗？此操作不可恢复。`)) return;
96	    
97	    try {
98	      if (report.contentType === 'POST') {
99	        await deletePostMutation.mutateAsync(report.contentId);
100	      } else {
101	        await deleteCommentMutation.mutateAsync(report.contentId);
102	      }
103	      await handleReportMutation.mutateAsync({ id: report.id, status: 'RESOLVED' });
104	    } catch (err: any) {
105	      setError(err.response?.data?.message || '操作失败');
106	    }
107	  };
108	
109	  const handleDismissReport = (reportId: number) => {
110	    if (!confirm('确定要忽略该举报吗？')) return;
111	    handleReportMutation.mutate({ id: reportId, status: 'DISMISSED' });
112	  };
113	
114	  const handleStatusChange = (postId: number, newStatus: string) => {
115	    statusMutation.mutate({ postId, status: newStatus });
116	  };
117	
118	  const handleDeletePost = (postId: number, title: string) => {
119	    if (!confirm(`确定要删除帖子「${title}」吗？`)) return;
120	    statusMutation.mutate({ postId, status: 'DELETED' });
121	  };
122	
123	  const handleDeleteComment = (commentId: number, content: string) => {
