126	    deleteCommentMutation.mutate(commentId);
127	  };
128	
129	  const getStatusColor = (status: string) => {
130	    switch (status) {
131	      case 'PUBLISHED': return '#2ecc71';
132	      case 'DRAFT': return '#f39c12';
133	      case 'DELETED': return '#e74c3c';
134	      default: return '#95a5a6';
135	    }
136	  };
137	
138	  const getStatusLabel = (status: string) => {
139	    switch (status) {
140	      case 'PUBLISHED': return '已发布';
141	      case 'DRAFT': return '草稿';
142	      case 'DELETED': return '已删除';
143	      default: return status;
144	    }
145	  };
146	
147	
148	  const clearMessages = () => {
149	    setError('');
150	    setSuccess('');
151	  };
152	
153	  return (
154	    <div>
155	      <h1 style={{ marginBottom: '1.5rem' }}>内容审核</h1>
156	
157	      {error && <ErrorMessage message={error} onDismiss={() => setError('')} />}
158	      {success && <ErrorMessage type="success" message={success} onDismiss={() => setSuccess('')} />}
159	
160	      {/* 标签页切换 */}
161	      <div className="card" style={{ marginBottom: '1.5rem', padding: '0.5rem 1rem' }}>
162	        <div style={{ display: 'flex', gap: '0.5rem' }}>
163	          <button
164	            className={`btn ${activeTab === 'posts' ? 'btn-primary' : ''}`}
165	            onClick={() => { setActiveTab('posts'); clearMessages(); }}
166	          >
167	            帖子审核
168	          </button>
169	          <button
170	            className={`btn ${activeTab === 'comments' ? 'btn-primary' : ''}`}
171	            onClick={() => { setActiveTab('comments'); clearMessages(); }}
172	          >
173	            评论审核
174	          </button>
175	          <button
176	            className={`btn ${activeTab === 'reports' ? 'btn-primary' : ''}`}
177	            onClick={() => { setActiveTab('reports'); clearMessages(); }}
178	          >
179	            举报队列
180	          </button>
181	        </div>
182	      </div>
183	
184	      {/* 帖子审核 */}
185	      {activeTab === 'posts' && (
186	        <>
187	          {/* 筛选器 */}
188	          <div className="card" style={{ marginBottom: '1.5rem', padding: '1rem' }}>
189	            <div className="filter-bar">
190	              <span>状态筛选：</span>
191	              <button
192	                className={`filter-btn ${filterStatus === '' ? 'filter-active' : ''}`}
193	                onClick={() => setFilterStatus('')}
194	              >
195	                全部
196	              </button>
197	              <button
198	                className={`filter-btn ${filterStatus === 'PUBLISHED' ? 'filter-active' : ''}`}
199	                onClick={() => setFilterStatus('PUBLISHED')}
200	              >
201	                已发布
202	              </button>
203	              <button
204	                className={`filter-btn ${filterStatus === 'DRAFT' ? 'filter-active' : ''}`}
205	                onClick={() => setFilterStatus('DRAFT')}
206	              >
207	                草稿
208	              </button>
209	              <button
210	                className={`filter-btn ${filterStatus === 'DELETED' ? 'filter-active' : ''}`}
211	                onClick={() => setFilterStatus('DELETED')}
212	              >
213	                已删除
214	              </button>
215	            </div>
216	          </div>
217	
218	          {postsLoading ? (
219	            <div className="loading-container">
220	              <div className="spinner spinner-lg"></div>
221	              <span>加载中...</span>
222	            </div>
223	          ) : (
224	            <div className="table-container">
225	              <div className="card">
226	                <p style={{ color: 'var(--color-text-muted)', marginBottom: '1rem' }}>共 {posts.length} 条帖子</p>
227	                {posts.length === 0 ? (
228	                  <div className="empty-state">暂无帖子</div>
229	                ) : (
230	                  <table className="data-table">
231	                    <thead>
232	                      <tr>
233	                        <th>标题</th>
234	                        <th>作者</th>
235	                        <th className="hide-mobile">版块</th>
236	                        <th>状态</th>
237	                        <th className="hide-mobile">浏览</th>
238	                        <th>操作</th>
239	                      </tr>
240	                    </thead>
241	                    <tbody>
242	                      {posts.map((post) => (
243	                        <tr key={post.id}>
244	                          <td style={{ maxWidth: '300px' }}>
245	                            <div style={{ fontWeight: '500', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
246	                              {post.title}
247	                            </div>
248	                            <div style={{ fontSize: '0.85rem', color: 'var(--color-text-muted)' }}>
249	                              {new Date(post.createdAt).toLocaleDateString()}
250	                            </div>
251	                          </td>
252	                          <td>{post.authorUsername}</td>
253	                          <td className="hide-mobile">{post.categoryName || '-'}</td>
