289	                              <button
290	                                className="btn btn-danger btn-sm"
291	                                onClick={() => handleDeletePost(post.id, post.title)}
292	                              >
293	                                删除
294	                              </button>
295	                            )}
296	                          </td>
297	                        </tr>
298	                      ))}
299	                    </tbody>
300	                  </table>
301	                )}
302	              </div>
303	            </div>
304	          )}
305	        </>
306	      )}
307	
308	      {/* 评论审核 */}
