323	                  <table className="data-table">
324	                    <thead>
325	                      <tr>
326	                        <th>内容</th>
327	                        <th>作者</th>
328	                        <th className="hide-mobile">所属帖子</th>
329	                        <th className="hide-mobile">时间</th>
330	                        <th>操作</th>
331	                      </tr>
