378	     */
379	    private Page<PostResponse> toPostResponsePage(Page<Post> posts) {
380	        List<Post> postList = posts.getContent();
381	
382	        Set<Long> authorIds = postList.stream()
383	                .map(Post::getAuthorId)
384	                .collect(Collectors.toSet());
385	
386	        Set<Long> categoryIds = postList.stream()
387	                .map(Post::getCategoryId)
388	                .filter(Objects::nonNull)
389	                .collect(Collectors.toSet());
390	
391	        Set<Long> postIds = postList.stream()
392	                .map(Post::getId)
393	                .collect(Collectors.toSet());
394	
395	        Map<Long, UserInfoDTO> userMap = batchResolveUsers(authorIds);
396	
397	        Map<Long, Category> categoryMap = categoryIds.isEmpty()
398	                ? Collections.emptyMap()
399	                : categoryRepository.findAllById(categoryIds).stream()
400	                        .collect(Collectors.toMap(Category::getId, c -> c));
401	
402	        Map<Long, Long> commentCountMap = batchCountComments(postIds);
403	
404	        return posts.map(post -> {
405	            UserInfoDTO author = userMap.get(post.getAuthorId());
406	            String authorUsername = author != null ? author.getUsername() : "未知用户";
407	            String avatarUrl = author != null ? author.getAvatarUrl() : null;
408	
409	            String categoryName = null;
410	            if (post.getCategoryId() != null) {
411	                Category category = categoryMap.get(post.getCategoryId());
412	                categoryName = category != null ? category.getName() : null;
413	            }
414	
415	            long commentCount = commentCountMap.getOrDefault(post.getId(), 0L);
416	
417	            PostResponse response = new PostResponse(
418	                    post.getId(),
419	                    post.getTitle(),
420	                    post.getContent(),
421	                    post.getAuthorId(),
422	                    authorUsername,
423	                    post.getCategoryId(),
424	                    categoryName,
425	                    post.getCreatedAt(),
426	                    post.getUpdatedAt(),
427	                    post.getViewCount(),
428	                    post.getStatus(),
429	                    commentCount
430	            );
431	            response.setAuthorAvatarUrl(normalizeAvatarUrl(avatarUrl));
432	            response.setLikeCount(post.getLikeCount() != null ? post.getLikeCount().longValue() : 0L);
433	            return response;
434	        });
435	    }
