496	    /**
497	     * 转换单个 Post 为 PostResponse（用于详情等单条查询场景）
498	     */
499	    private PostResponse toPostResponse(Post post, String authorUsername, String avatarUrl) {
500	        String categoryName = null;
501	        if (post.getCategoryId() != null) {
502	            Category category = categoryRepository.findById(post.getCategoryId()).orElse(null);
503	            categoryName = category != null ? category.getName() : null;
504	        }
505	
506	        long commentCount = commentRepository.countByPostIdAndStatus(post.getId(), "PUBLISHED");
507	
508	        PostResponse response = new PostResponse(
509	                post.getId(),
510	                post.getTitle(),
511	                post.getContent(),
512	                post.getAuthorId(),
513	                authorUsername,
514	                post.getCategoryId(),
515	                categoryName,
516	                post.getCreatedAt(),
517	                post.getUpdatedAt(),
518	                post.getViewCount(),
519	                post.getStatus(),
520	                commentCount
521	        );
522	
523	        response.setAuthorAvatarUrl(normalizeAvatarUrl(avatarUrl));
524	        response.setLikeCount(post.getLikeCount() != null ? post.getLikeCount().longValue() : 0L);
525	
526	        return response;
527	    }
