533	    /**
534	     * Batch resolve user info via a single Feign call instead of N individual calls.
535	     */
536	    private Map<Long, UserInfoDTO> batchResolveUsers(Set<Long> authorIds) {
537	        if (authorIds.isEmpty()) {
538	            return Collections.emptyMap();
539	        }
540	        List<Long> idList = new ArrayList<>(authorIds);
541	        List<UserInfoDTO> users = userServiceClient.getUsersByIds(idList);
542	        return users.stream()
543	                .filter(u -> u.getId() != null)
544	                .collect(Collectors.toMap(UserInfoDTO::getId, u -> u));
545	    }
546	
547	    /**
548	     * Batch count comments for multiple posts in a single query.
549	     */
550	    private Map<Long, Long> batchCountComments(Set<Long> postIds) {
551	        if (postIds.isEmpty()) {
552	            return Collections.emptyMap();
553	        }
554	        return commentRepository.countByPostIdInAndStatus(postIds, "PUBLISHED")
555	                .stream()
556	                .collect(Collectors.toMap(
557	                        row -> (Long) row[0],
558	                        row -> (Long) row[1]
559	                ));
560	    }
561	}
