6	import com.cc91.forumservice.dto.UpdatePostRequest;
7	import com.cc91.forumservice.exception.UnauthorizedException;
8	import com.cc91.forumservice.service.PostService;
9	import jakarta.validation.Valid;
10	import org.springframework.data.domain.Page;
11	import org.springframework.http.ResponseEntity;
12	import org.springframework.security.core.Authentication;
13	import org.springframework.security.core.context.SecurityContextHolder;
14	import org.springframework.web.bind.annotation.*;
15	
16	import java.util.Map;
17	
18	/**
19	 * 帖子控制器
20	 * 处理帖子相关的请求
21	 */
22	@RestController
23	@RequestMapping("/api/posts")
24	public class PostController {
25	
26	    private final PostService postService;
27	
28	    public PostController(PostService postService) {
29	        this.postService = postService;
30	    }
31	
32	    /**
33	     * 创建帖子
34	     * POST /api/posts
35	     */
