5	import org.slf4j.Logger;
6	import org.slf4j.LoggerFactory;
7	import org.springframework.beans.factory.annotation.Value;
8	import org.springframework.stereotype.Component;
9	
10	import javax.crypto.SecretKey;
11	import java.nio.charset.StandardCharsets;
12	import java.util.Date;
13	
14	/**
15	 * JWT 工具类
16	 * 用于生成、解析和验证 JWT 令牌
17	 */
18	@Component
19	public class JwtUtil {
20	
21	    private static final Logger logger = LoggerFactory.getLogger(JwtUtil.class);
22	
23	    @Value("${jwt.secret}")
24	    private String secret;
25	
26	    @Value("${jwt.expiration}")
27	    private Long expiration;
28	
29	    /**
30	     * 生成 JWT 令牌
31	     */
32	    public String generateToken(String username) {
33	        Date now = new Date();
34	        Date expiryDate = new Date(now.getTime() + expiration);
35	
36	        return Jwts.builder()
37	                .subject(username)
38	                .issuedAt(now)
39	                .expiration(expiryDate)
40	                .signWith(getSigningKey())
41	                .compact();
42	    }
43	
44	    /**
45	     * 从 JWT 令牌中获取用户名
46	     */
47	    public String getUsernameFromToken(String token) {
48	        Claims claims = getClaimsFromToken(token);
49	        return claims.getSubject();
50	    }
51	
52	    /**
53	     * 从 JWT 令牌中获取用户ID
54	     */
55	    public Long getUserIdFromToken(String token) {
56	        Claims claims = getClaimsFromToken(token);
57	        return claims.get("userId", Long.class);
58	    }
59	
60	    /**
61	     * 验证 JWT 令牌
62	     */
63	    public boolean validateToken(String token) {
64	        try {
65	            Jwts.parser()
66	                .verifyWith(getSigningKey())
67	                .build()
68	                .parseSignedClaims(token);
69	            return true;
70	        } catch (SecurityException ex) {
71	            logger.error("Invalid JWT signature: {}", ex.getMessage());
72	        } catch (MalformedJwtException ex) {
73	            logger.error("Invalid JWT token: {}", ex.getMessage());
74	        } catch (ExpiredJwtException ex) {
